\label{p:1}
Let $G$ be a nontrivial abelian group.
\begin{itemize}
\item[(i)]  $\mathrm{Prob}_r(G) = \frac{1}{|G[r]|}$. Furthermore, if $r$ is prime,  $\mathrm{Prob}_r(G)=\frac{1}{|G|}$ if and only if $G\simeq C^k_r$ for some $k\geq 1$.
\item[(ii)] The sets $X$  and $Y$ of Remark \ref{r:1} coincide.
\end{itemize}

\label{r:2}
 Let $G$ be a nontrivial group.
\begin{itemize}
\item[(i)] $\mathrm{Prob}_r(G)=1$ if and only if $|G|=|G^r|$, that is, the number of the elements of $G$ having an $r$--th root is the same of the number of the elements of
$G$. 
\item[(ii)](See \cite{lp2}) The number of solutions of the equation $x^r = a$ in $G$ is
a multiple of $\mathrm{gcd}(r, |C_G(a)|)$, where $r\geq 2$ and $a$, $x\in G$. In particular, the number of solutions of the equation $x^r = 1$ over $G$ is a multiple of $\mathrm{gcd}(r, |G|)$ and when $r$ is prime, $|x|=|a|$ or $|x|=r|a|$.
\end{itemize}

\label{p:2}
Let $G$ be an arbitrary group and $r\ge2$.  $\mathrm{Prob}_r(G)=1$ if and only if
some multiple of $gcd(r, |G|)$ is equal to $1$.
